/**
 * Tour.Target: the part a step points at, which adds no box.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/overlays/tour.module.css'

export interface TourTargetProps {
  /**
   * The name a step's `target` uses.
   */
  name: string
  /**
   * The part the step points at.
   */
  children: JSX.Element
}

/** Tour.Target: the part a step points at, which adds no box. */
export default function TourTarget(given: TourTargetProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <span class={styles.target} data-tour-target={props.name}>
        {props.children}
      </span>
    )
  })
}
